#!/usr/bin/env python3
import sys
import os

def check_path(path: str, is_dir: bool = False) -> bool:
    """Return True if the path exists (and is a directory when is_dir=True)."""
    if is_dir:
        return os.path.isdir(path)
    return os.path.isfile(path)

def check_file_contains(filepath: str, keyword: str) -> bool:
    """Return True if the file exists and contains the given keyword."""
    if not os.path.isfile(filepath):
        return False
    try:
        with open(filepath, "r", encoding="utf-8") as f:
            return any(keyword in line for line in f)
    except Exception:
        return False

def main():
    errors = []

    # 1. 必须存在 src/ 目录
    if not check_path("src", is_dir=True):
        errors.append("缺少 src/ 目录")

    # 2. 必须存在 tests/ 目录
    if not check_path("tests", is_dir=True):
        errors.append("缺少 tests/ 目录")

    # 3. 必须存在 README.md 并且包含 “M2” 关键字
    if not check_file_contains("README.md", "M2"):
        errors.append("README.md 不存在或未包含关键字 'M2'")

    # 4. 必须存在 requirements.txt
    if not check_path("requirements.txt"):
        errors.append("缺少 requirements.txt 文件")

    # 5. 必须存在 M2_DELIVERABLES.txt 并且包含 “ACCEPTED”
    if not check_file_contains("M2_DELIVERABLES.txt", "ACCEPTED"):
        errors.append("M2_DELIVERABLES.txt 不存在或未标记为 ACCEPTED")

    if errors:
        print("验收失败，未满足以下条件：")
        for e in errors:
            print(f"- {e}")
        sys.exit(1)
    else:
        print("All acceptance criteria passed.")
        sys.exit(0)

if __name__ == "__main__":
    main()
